'use strict';

// MODULES //

var rfftf = require( './rfftf.js' );


// MAIN //

/**
* Computes the discrete Fourier cosine transform of a sequence.
*
* @param {number} n - sequence length
* @param {Float64Array} x - input array
* @param {number} xptr - starting index for x
* @param {Float64Array} wsave - working array
* @param {number} wptr - starting index for wsave
* @returns {void}
*/
function cost( n, x, xptr, wsave, wptr ) {
	var x1p3;
	var xim2;
	var modn;
	var nm1;
	var np1;
	var x1h;
	var ns2;
	var tx2;
	var c1;
	var t1;
	var t2;
	var kc;
	var xi;
	var i;
	var k;

	xptr -= 1;
	wptr -= 1;

	// Function Body
	nm1 = n - 1;
	np1 = n + 1;
	ns2 = n / 2;
	if ( n === 2 ) {
		x1h = x[ xptr + 1 ] + x[ xptr + 2 ];
		x[ xptr + 2 ] = x[ xptr + 1 ] - x[ xptr + 2 ];
		x[ xptr + 1 ] = x1h;
	} else if ( n === 3 ) {
		x1p3 = x[ xptr + 1 ] + x[ xptr + 3 ];
		tx2 = x[ xptr + 2 ] + x[ xptr + 2 ];
		x[ xptr + 2 ] = x[ xptr + 1 ] - x[ xptr + 3 ];
		x[ xptr + 1 ] = x1p3 + tx2;
		x[ xptr + 3 ] = x1p3 - tx2;
	} else if ( n > 3 ) {
		c1 = x[ xptr + 1 ] - x[ xptr + n ];
		x[ xptr + 1 ] += x[ xptr + n ];
		for ( k = 2; k <= ns2; k++ ) {
			kc = np1 - k;
			t1 = x[ xptr + k ] + x[ xptr + kc ];
			t2 = x[ xptr + k ] - x[ xptr + kc ];
			c1 += wsave[ wptr + kc ] * t2;
			t2 *= wsave[ wptr + k ];
			x[ xptr + k ] = t1 - t2;
			x[ xptr + kc ] = t1 + t2;
		}
		modn = n % 2;
		if ( modn !== 0 ) {
			x[ xptr + ns2 + 1 ] += x[ xptr + ns2 + 1 ];
		}
		rfftf( nm1, x, xptr + 1, wsave, wptr + n + 1 );
		xim2 = x[ xptr + 2 ];
		x[ xptr + 2 ] = c1;
		for ( i = 4; i <= n; i += 2 ) {
			xi = x[ xptr + i ];
			x[ xptr + i ] = x[ xptr + i - 2 ] - x[ xptr + i - 1 ];
			x[ xptr + i - 1 ] = xim2;
			xim2 = xi;
		}
		if ( modn !== 0 ) {
			x[ xptr + n ] = xim2;
		}
	}
}


// EXPORTS //

module.exports = cost;
